theorem weightedDirection_integrableOn (a b x : ℝ) {ρ : ℝ → ℝ}
    (hρ : Continuous ρ) :
    IntegrableOn (fun r : ℝ => ρ (x - r) • direction r) (Set.Icc a b) volume

theorem weightedScenery_integrableOn (a b x : ℝ) {ρ : ℝ → ℝ}
    (hρ : Continuous ρ) :
    IntegrableOn (fun r : ℝ => ρ (x - r) • sourceScenery r) (Set.Icc a b) volume

theorem dilate_support {ρ : ℝ → ℝ} {R ε : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ R) (hε : 0 < ε) {z : ℝ}
    (hz : dilate ρ ε z ≠ 0) : |z| ≤ ε * R

theorem shifted_support {ρ : ℝ → ℝ} {R ε : ℝ}
    (hs : ∀ z, ρ z ≠ 0 → |z| ≤ R) (hε : 0 < ε) (x r : ℝ)
    (hr : r ∉ Set.Icc (x - ε * R) (x + ε * R)) : dilate ρ ε (x-r) = 0

theorem spatial_hasDerivAt (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 1 ρ) (r : ℝ) :
    HasDerivAt (spatial g a ρ) (slope g a ρ r) r

theorem slope_hasDerivAt (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) (r : ℝ) :
    HasDerivAt (slope g a ρ) (curvature g a ρ r) r

theorem slope_bound (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ r, ‖slope g a ρ r‖ ≤ C

theorem curvature_bound (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 2 ρ) :
    ∃ C : ℝ, 0 ≤ C ∧ ∀ r, ‖curvature g a ρ r‖ ≤ C

def field (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    Lp GaussianL2 2 (PredictableRealL2.horizonMeasure T gaussianProduct)

theorem scalarPrimitive_C2 (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (L : GaussianL2 →L[ℝ] ℝ) :
    ContDiff ℝ 2 (scalarPrimitive g a ρ L)

theorem scalarPrimitive_deriv (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (L : GaussianL2 →L[ℝ] ℝ) (r : ℝ) :
    deriv (scalarPrimitive g a ρ L) r = L (slope g a ρ r)

theorem scalarPrimitive_second_deriv (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (L : GaussianL2 →L[ℝ] ℝ) (r : ℝ) :
    deriv (deriv (scalarPrimitive g a ρ L)) r = L (curvature g a ρ r)

theorem endpoint_memLp (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    MemLp (fun ω => spatial g a ρ |clockPath ω T|) 2 gaussianProduct

theorem wholeCorrection_memLp (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    MemLp (wholeCorrection g a ρ T) 2 gaussianProduct

theorem finite_kernel_identity (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    endpointClass g a hc hρ T = integralValue g a hc hρ T+wholeClass g a hc hρ T

theorem dilated_kernel_identity (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) {ε : ℝ} (hε : 0 < ε) (T : ℝ≥0) :
    let hd

def trimmedMap (T : ℝ≥0)
    (A : Lp ℝ 2 (predictableMeasure T) →L[ℝ] Lp ℝ 2 (predictableMeasure T)) :
    Lp GaussianL2 2 (predictableMeasure T) →L[ℝ] Lp GaussianL2 2 (predictableMeasure T)

def mapPredictable (T : ℝ≥0)
    (A : Lp ℝ 2 (predictableMeasure T) →L[ℝ] Lp ℝ 2 (predictableMeasure T)) :
    Domain T →L[ℝ] Domain T

theorem ambient_eq_of_tests {u v : Ambient}
    (h : ∀ L : GaussianL2 →L[ℝ] ℝ, L.compLpL 2 timeProbability u = L.compLpL 2 timeProbability v) :
    u = v

theorem profile_memLp (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    MemLp (profileValue g a ρ T) 2 GaussianCore.γ

theorem profile_ae (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    profile g a hc hρ T =ᵐ[GaussianCore.γ] profileValue g a ρ T

theorem pointSlope_memLp (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    MemLp (fun ω => signedSlope g a ρ (clockPath ω T)) 2 gaussianProduct

theorem pointSlope_ae (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) (T : ℝ≥0) :
    pointSlope g a hc hρ T =ᵐ[gaussianProduct] fun ω => signedSlope g a ρ (clockPath ω T)

theorem tested_closed_graph (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) {T : ℝ≥0}
    (hT : 0 < T) (L : GaussianL2 →L[ℝ] ℝ) :
    (L.compLpL 2 gaussianProduct (endpointClass g a hc hρ T),
      scalarTensor (unitDirection T) (L.compLpL 2 gaussianProduct
        (Real.sqrt (T : ℝ) • pointSlope g a hc hρ T))) ∈ closedCylindricalDerivative.graph

theorem recoveredSlope_unique (g : SchwartzMap ℝ ℝ) (a : ℝ) {ρ : ℝ → ℝ}
    (hc : HasCompactSupport ρ) (hρ : ContDiff ℝ 3 ρ) {T : ℝ≥0} (hT : 0 < T) {q : Field}
    (hq : ∀ k, clockLift (GaussianNumberSectors.projection k) q =
      (k+1 : ℝ)⁻¹ • clockLift (GaussianNumberSectors.projection k) (pointSlope g a hc hρ T)) :
    q = recoveredSlope g a hc hρ T
